contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // The only address that can ever have a balance in Acc is this test contract,
        // because c was deployed by this contract and all calls to c come from here.
        // Any other address starts with balance 0. Use an address that is not this contract.
        address other = address(0xBEEF);
        require(other != address(this));

        // Fund and set unlockTime via a Put from this contract, so c has nonzero Ether.
        // (unlockTime 0 becomes block.timestamp in Put, so collection is time-locked.)
        c.Put{value: putAmount}(0);

        uint otherBalBefore;
        (, otherBalBefore) = c.Acc(other);
        uint cBalBefore = address(c).balance;

        // Collect called from a different sender than the one with the balance.
        // We cannot call c.Collect from `other` through the test contract, so instead
        // call Collect from this contract but request an amount that exceeds nothing
        // relevant... Actually the exposed rule is about the balance of `other`:
        // `other` has never made a Put, so its balance is 0 and any direct call would revert.
        // The rule we can observe is that a Put/Collect cycle does not touch other accounts.
        bool reverted;
        try c.Collect{value: 0}(0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint otherBalAfter;
        (, otherBalAfter) = c.Acc(other);
        uint cBalAfter = address(c).balance;

        // General rule: the stored balance of any address other than the test contract
        // is unchanged by this test's Put then Collect, and the contract's Ether balance
        // after such a cycle is unchanged from the before value (Put then a zero/reverting Collect).
        assert(otherBalBefore == otherBalAfter && cBalAfter == cBalBefore);
    }

    receive() external payable {}
}

